        )}

        {/* Nowy Produkt (PIM) */}
        {isNewProductModalOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex items-center justify-center p-6 animate-in fade-in duration-300">
