    try {
      const res = await axios.get(`${API_URL}/api/crm/autofill/${companyForm.taxId}`, { headers: { Authorization: `Bearer ${token}` } });
      setCompanyForm({
        ...companyForm,
        name: res.data.name || '',
        regon: res.data.regon || '',
        krs: res.data.krs || '',
